Identify the data sheets as all sheets except `Totals`, then sum the cached `AB` column values for rows 5–29 across those sheets. Write the resulting totals into `Totals!B2:B26`, matching the existing `B2` example. Save the workbook with plain values only.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

totals_ws = wb["Totals"]
v_totals = vals["Totals"]

data_sheets = [name for name in vals.sheetnames if name != "Totals"]

def to_number(value):
    if isinstance(value, bool):
        return 0
    if isinstance(value, (int, float)):
        return value
    if isinstance(value, str):
        try:
            return float(value)
        except ValueError:
            return 0
    return 0

for row in range(2, 27):
    code = v_totals.cell(row=row, column=1).value
    total = 0

    for sheet_name in data_sheets:
        v_ws = vals[sheet_name]
        if code is None:
            ab_value = v_ws.cell(row=row + 3, column=28).value
        else:
            ab_value = None
            for r in range(5, 30):
                if v_ws.cell(row=r, column=1).value == code:
                    ab_value = v_ws.cell(row=r, column=28).value
                    break

        total += to_number(ab_value)

    if isinstance(total, float) and total.is_integer():
        total = int(total)

    totals_ws.cell(row=row, column=2).value = total

    if row <= 5:
        print(row, code, total)

wb.save(OUT)
